begin;
alter table fp.travel_trips add column if not exists home_currency text not null default 'NZD' check(home_currency~'^[A-Z]{3}$');
alter table fp.travel_trips add column if not exists budget numeric check(budget is null or budget>=0);
alter table fp.travel_trips add column if not exists notes text check(notes is null or char_length(notes)<=500);

create table if not exists fp.travel_trip_travellers(id uuid primary key default gen_random_uuid(),trip_id uuid not null references fp.travel_trips(id) on delete cascade,household_id uuid not null references fp.households(id) on delete cascade,name text not null check(char_length(name) between 1 and 100),member_user_id uuid,created_by uuid not null,created_at timestamptz not null default now(),unique(trip_id,name));
create table if not exists fp.travel_trip_shares(trip_id uuid not null references fp.travel_trips(id) on delete cascade,member_user_id uuid not null,access_level text not null check(access_level in ('view','contribute','manage')),granted_by uuid not null,granted_at timestamptz not null default now(),primary key(trip_id,member_user_id));
create table if not exists fp.travel_cost_entries(id uuid primary key default gen_random_uuid(),trip_id uuid not null references fp.travel_trips(id) on delete cascade,household_id uuid not null references fp.households(id) on delete cascade,travel_record_id uuid references fp.travel_records(id) on delete set null,category text not null check(category in ('transport','accommodation','food','activity','insurance','visa','other')),cost_status text not null check(cost_status in ('estimated','booked','paid','refunded','outstanding')),amount numeric not null check(amount>=0),currency text not null check(currency~'^[A-Z]{3}$'),exchange_rate_to_home numeric check(exchange_rate_to_home is null or exchange_rate_to_home>0),rate_source text check(rate_source is null or char_length(rate_source)<=120),rate_date date,notes text check(notes is null or char_length(notes)<=500),confirmed_by uuid not null,confirmed_at timestamptz not null default now(),check((exchange_rate_to_home is null and rate_source is null and rate_date is null) or (exchange_rate_to_home is not null and rate_source is not null and rate_date is not null)));
alter table fp.travel_trip_travellers enable row level security;alter table fp.travel_trip_travellers force row level security;alter table fp.travel_trip_shares enable row level security;alter table fp.travel_trip_shares force row level security;alter table fp.travel_cost_entries enable row level security;alter table fp.travel_cost_entries force row level security;
create policy travel_traveller_authorised_read on fp.travel_trip_travellers for select using(exists(select 1 from fp.travel_trips t where t.id=trip_id and (fp.is_household_admin(t.household_id) or t.created_by=fp.current_user_id() or exists(select 1 from fp.travel_trip_shares s where s.trip_id=t.id and s.member_user_id=fp.current_user_id()))));
create policy travel_share_authorised_read on fp.travel_trip_shares for select using(member_user_id=fp.current_user_id() or exists(select 1 from fp.travel_trips t where t.id=trip_id and (fp.is_household_admin(t.household_id) or t.created_by=fp.current_user_id())));
create policy travel_cost_authorised_read on fp.travel_cost_entries for select using(exists(select 1 from fp.travel_trips t where t.id=trip_id and (fp.is_household_admin(t.household_id) or t.created_by=fp.current_user_id() or exists(select 1 from fp.travel_trip_shares s where s.trip_id=t.id and s.member_user_id=fp.current_user_id()))));

create or replace function fp.can_manage_trip(trip uuid,required text default 'contribute') returns boolean language sql stable security definer set search_path=pg_catalog,fp as $$select exists(select 1 from fp.travel_trips t where t.id=trip and (fp.is_household_admin(t.household_id) or t.created_by=fp.current_user_id() or exists(select 1 from fp.travel_trip_shares s where s.trip_id=t.id and s.member_user_id=fp.current_user_id() and (s.access_level='manage' or required='view' or (required='contribute' and s.access_level='contribute')))))$$;
create or replace function fp.update_travel_trip(trip uuid,trip_name text,destination_name text,trip_start date,trip_end date,home_currency_code text,budget_amount numeric,trip_status text,trip_notes text default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,fp as $$begin if not fp.can_manage_trip(trip,'manage') then raise exception 'not authorised' using errcode='42501';end if;if char_length(trim(trip_name)) not between 1 and 120 or upper(home_currency_code)!~'^[A-Z]{3}$' or budget_amount<0 or trip_status not in ('planned','active','completed','cancelled') or (trip_end is not null and trip_start is not null and trip_end<trip_start) then raise exception 'invalid trip' using errcode='22023';end if;update fp.travel_trips set name=trim(trip_name),destination=nullif(left(trim(destination_name),160),''),start_date=trip_start,end_date=trip_end,home_currency=upper(home_currency_code),budget=budget_amount,status=trip_status,notes=nullif(left(trim(trip_notes),500),'') where id=trip;return jsonb_build_object('id',trip,'status',trip_status);end$$;
create or replace function fp.add_trip_traveller(trip uuid,traveller_name text,member uuid default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,fp as $$declare t fp.travel_trips;row fp.travel_trip_travellers;begin if not fp.can_manage_trip(trip,'contribute') then raise exception 'not authorised' using errcode='42501';end if;select * into t from fp.travel_trips where id=trip;if char_length(trim(traveller_name)) not between 1 and 100 or (member is not null and not exists(select 1 from fp.members m where m.household_id=t.household_id and m.user_id=member and m.status='active')) then raise exception 'invalid traveller' using errcode='22023';end if;insert into fp.travel_trip_travellers(trip_id,household_id,name,member_user_id,created_by) values(t.id,t.household_id,trim(traveller_name),member,fp.current_user_id()) returning * into row;return jsonb_build_object('id',row.id,'name',row.name);end$$;
create or replace function fp.set_trip_share(trip uuid,member uuid,access text) returns jsonb language plpgsql security definer set search_path=pg_catalog,fp as $$declare t fp.travel_trips;begin select * into t from fp.travel_trips where id=trip;if t.id is null or not(fp.is_household_admin(t.household_id) or t.created_by=fp.current_user_id()) or not exists(select 1 from fp.members m where m.household_id=t.household_id and m.user_id=member and m.status='active') then raise exception 'not authorised' using errcode='42501';end if;if access='none' then delete from fp.travel_trip_shares where trip_id=trip and member_user_id=member;elsif access in ('view','contribute','manage') then insert into fp.travel_trip_shares(trip_id,member_user_id,access_level,granted_by) values(trip,member,access,fp.current_user_id()) on conflict(trip_id,member_user_id) do update set access_level=excluded.access_level,granted_by=excluded.granted_by,granted_at=now();else raise exception 'invalid access' using errcode='22023';end if;return jsonb_build_object('trip_id',trip,'member_user_id',member,'access',access);end$$;
create or replace function fp.add_travel_cost(trip uuid,record uuid,category text,cost_status text,amount numeric,currency text,exchange_rate numeric default null,rate_source text default null,rate_date date default null,notes text default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,fp as $$declare t fp.travel_trips;row fp.travel_cost_entries;begin if not fp.can_manage_trip(trip,'contribute') then raise exception 'not authorised' using errcode='42501';end if;select * into t from fp.travel_trips where id=trip;if category not in ('transport','accommodation','food','activity','insurance','visa','other') or cost_status not in ('estimated','booked','paid','refunded','outstanding') or amount<0 or upper(currency)!~'^[A-Z]{3}$' or ((exchange_rate is null)<>(rate_source is null) or (exchange_rate is null)<>(rate_date is null)) or (record is not null and not exists(select 1 from fp.travel_records r where r.id=record and r.trip_id=trip)) then raise exception 'invalid travel cost' using errcode='22023';end if;insert into fp.travel_cost_entries(trip_id,household_id,travel_record_id,category,cost_status,amount,currency,exchange_rate_to_home,rate_source,rate_date,notes,confirmed_by) values(t.id,t.household_id,record,category,cost_status,amount,upper(currency),exchange_rate,nullif(left(trim(rate_source),120),''),rate_date,nullif(left(trim(notes),500),''),fp.current_user_id()) returning * into row;return jsonb_build_object('id',row.id,'trip_id',row.trip_id);end$$;

create or replace function fp.travel_workspace() returns jsonb language plpgsql security definer set search_path=pg_catalog,fp as $$declare uid uuid:=fp.current_user_id();hid uuid;begin select household_id into hid from fp.members where user_id=uid and status='active' order by joined_at limit 1;if hid is null then return jsonb_build_object('trips','[]'::jsonb,'records','[]'::jsonb,'travellers','[]'::jsonb,'shares','[]'::jsonb,'costs','[]'::jsonb);end if;return jsonb_build_object('trips',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'destination',t.destination,'start_date',t.start_date,'end_date',t.end_date,'status',t.status,'home_currency',t.home_currency,'budget',t.budget,'notes',t.notes,'can_manage',fp.can_manage_trip(t.id,'manage'),'can_contribute',fp.can_manage_trip(t.id,'contribute')) order by coalesce(t.start_date,'9999-12-31')) from fp.travel_trips t where t.household_id=hid and fp.can_manage_trip(t.id,'view')),'[]'::jsonb),'records',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'trip_id',r.trip_id,'document_id',r.document_id,'document_title',d.title,'trip_name',t.name,'travel_kind',r.travel_kind,'booking_reference',r.booking_reference,'provider',r.provider,'origin',r.origin,'destination',r.destination,'starts_at',r.starts_at,'ends_at',r.ends_at,'amount',r.amount,'currency',r.currency,'notes',r.notes) order by coalesce(r.starts_at,r.confirmed_at)) from fp.travel_records r join fp.travel_trips t on t.id=r.trip_id join fp.documents d on d.id=r.document_id where r.household_id=hid and fp.can_manage_trip(t.id,'view') and (fp.is_household_admin(hid) or d.created_by=uid or exists(select 1 from fp.document_permissions p where p.document_id=d.id and p.member_user_id=uid))),'[]'::jsonb),'travellers',coalesce((select jsonb_agg(to_jsonb(v) order by v.name) from fp.travel_trip_travellers v where v.household_id=hid and fp.can_manage_trip(v.trip_id,'view')),'[]'::jsonb),'shares',coalesce((select jsonb_agg(to_jsonb(s)) from fp.travel_trip_shares s join fp.travel_trips t on t.id=s.trip_id where t.household_id=hid and (fp.is_household_admin(hid) or t.created_by=uid or s.member_user_id=uid)),'[]'::jsonb),'costs',coalesce((select jsonb_agg(to_jsonb(c) order by c.confirmed_at) from fp.travel_cost_entries c where c.household_id=hid and fp.can_manage_trip(c.trip_id,'view')),'[]'::jsonb));end$$;
revoke all on fp.travel_trip_travellers,fp.travel_trip_shares,fp.travel_cost_entries from public,anon,authenticated;revoke execute on function fp.can_manage_trip(uuid,text),fp.update_travel_trip(uuid,text,text,date,date,text,numeric,text,text),fp.add_trip_traveller(uuid,text,uuid),fp.set_trip_share(uuid,uuid,text),fp.add_travel_cost(uuid,uuid,text,text,numeric,text,numeric,text,date,text) from public,anon;grant execute on function fp.travel_workspace(),fp.update_travel_trip(uuid,text,text,date,date,text,numeric,text,text),fp.add_trip_traveller(uuid,text,uuid),fp.set_trip_share(uuid,uuid,text),fp.add_travel_cost(uuid,uuid,text,text,numeric,text,numeric,text,date,text) to authenticated;
commit;
